questions.starter:
def record_turn(phrase, history=[]):
    history.append(phrase)
    return history

questions.tests:
def test_independent_games():
    a = record_turn("sell")
    b = record_turn("buy")
    assert a == ["sell"] and b == ["buy"]
def test_not_same_object():
    assert record_turn("x") is not record_turn("y")
def test_explicit_history_kept():
    h = ["open"]
    assert record_turn("sell", h) == ["open", "sell"]
    assert h == ["open", "sell"]

questions.model:
def record_turn(phrase, history=None):
    if history is None:
        history = []
    history.append(phrase)
    return history
